package com.example.rokidgeminisecretary;
import android.content.*;import org.json.*;import java.util.*;import java.io.*;
/** User-confirmed local task board. No guessed assignees/dates or calendar writes. */
final class MeetingTaskBoard {
 static JSONObject source(Context c,String id)throws Exception{File folder=MeetingAudioStore.folder(c,id);MeetingAudioStore.meta(folder);File file=new File(folder,"summary.gcm");if(!file.isFile()||file.length()>1000000)throw new IOException("保存済み要約がありません");byte[] bytes=RecorderPhotoStore.read(file);String summary=new String(bytes,java.nio.charset.StandardCharsets.UTF_8);return new JSONObject().put("meetingId",id).put("sourceHash",RecorderPhotoStore.hash(bytes)).put("items",MaintenancePolicy.taskCandidates(summary));}
 static synchronized JSONArray list(Context c)throws Exception{JSONArray a=ReviewStore.read(c,"task-board").optJSONArray("items");return a==null?new JSONArray():a;}
 static synchronized JSONObject save(Context c,JSONObject in)throws Exception{JSONObject source=source(c,in.getString("meetingId"));if(!source.getString("sourceHash").equals(in.getString("sourceHash")))throw new IOException("要約が変わりました。候補を開き直してください");int index=in.getInt("index");JSONArray candidates=source.getJSONArray("items");if(index<0||index>=candidates.length())throw new IOException("候補を選び直してください");String title=in.getString("title").trim(),person=in.getString("assignee").trim(),due=in.getString("due").trim();if(title.isEmpty()||title.length()>800||person.length()>120||due.length()>10)throw new IOException("内容・担当者・期限を確認してください");if(!due.isEmpty())java.time.LocalDate.parse(due);String id=UUID.nameUUIDFromBytes((source.getString("meetingId")+":"+source.getString("sourceHash")+":"+index).getBytes(java.nio.charset.StandardCharsets.UTF_8)).toString();JSONArray all=list(c);for(int i=0;i<all.length();i++)if(id.equals(all.getJSONObject(i).getString("id"))){JSONObject old=all.getJSONObject(i);if(!title.equals(old.getString("title"))||!person.equals(old.getString("assignee"))||!due.equals(old.getString("due")))throw new IOException("この候補は既に別内容で保存済みです");return old;}if(all.length()>=100)throw new IOException("タスクは100件までです。完了項目を整理してください");JSONObject row=new JSONObject().put("id",id).put("meetingId",source.getString("meetingId")).put("sourceHash",source.getString("sourceHash")).put("excerpt",candidates.getJSONObject(index).getString("text")).put("title",title).put("assignee",person).put("due",due).put("state","pending").put("revision",1).put("at",System.currentTimeMillis());all.put(row);ReviewStore.write(c,"task-board",new JSONObject().put("items",all));return row;}
 static synchronized JSONObject change(Context c,String id,int revision,String state)throws Exception{if(!state.matches("pending|done|remove"))throw new IOException("状態が不正です");JSONArray all=list(c),next=new JSONArray();JSONObject target=null;for(int i=0;i<all.length();i++){JSONObject row=all.getJSONObject(i);if(id.equals(row.getString("id"))){if(revision!=row.getInt("revision"))throw new IOException("状態が変わりました");target=row;if(!state.equals("remove")){snapshot(row);row.put("state",state).put("revision",revision+1);}else {if(!row.getString("state").equals("done"))throw new IOException("完了したタスクだけ整理できます");continue;}}next.put(row);}if(target==null)throw new IOException("タスクがありません");ReviewStore.write(c,"task-board",new JSONObject().put("items",next));return target;}
 static synchronized JSONObject edit(Context c,JSONObject in)throws Exception{JSONArray all=list(c);for(int i=0;i<all.length();i++){JSONObject row=all.getJSONObject(i);if(!in.getString("id").equals(row.getString("id")))continue;if(in.getInt("revision")!=row.getInt("revision"))throw new IOException("タスクが更新されました");String title=in.getString("title").trim(),person=in.getString("assignee").trim(),due=in.getString("due").trim();if(title.isEmpty()||title.length()>800||person.length()>120||due.length()>10)throw new IOException("本文・担当・期限を確認してください");if(!due.isEmpty())java.time.LocalDate.parse(due);snapshot(row);row.put("title",title).put("assignee",person).put("due",due).put("revision",row.getInt("revision")+1).put("updatedAt",System.currentTimeMillis());ReviewStore.write(c,"task-board",new JSONObject().put("items",all));return row;}throw new IOException("タスクがありません");}
 static void snapshot(JSONObject row)throws Exception{JSONArray old=row.optJSONArray("history"),next=new JSONArray();for(int i=old==null?0:Math.max(0,old.length()-9);old!=null&&i<old.length();i++)next.put(old.get(i));next.put(new JSONObject().put("title",row.getString("title")).put("assignee",row.optString("assignee")).put("due",row.optString("due")).put("state",row.getString("state")).put("revision",row.getInt("revision")).put("savedAt",System.currentTimeMillis()));row.put("history",next);}
 private MeetingTaskBoard(){}
}
